const auth = $input.first().json.headers?.authorization || '';
if (!auth.startsWith('Bearer ')) {
  return [{ json: { _error: 'AUTH_MISSING_TOKEN', _status: 401 } }];
}
const token = auth.slice(7);
try {
  const parts = token.split('.');
  if (parts.length !== 3) throw new Error('JWT malformed');
  const payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8'));
  if (!payload.sub) throw new Error('No sub claim');
  if (payload.exp && Date.now()/1000 > payload.exp) throw new Error('JWT expired');
  if (!payload.tenant_id) throw new Error('No tenant_id claim');

  const q = $input.first().json.query || {};
  const agentName = (q.agent_name || '').trim();
  if (!agentName) {
    return [{ json: { _error: 'VALIDATION_MISSING_AGENT', _status: 400, _details: 'agent_name query param is required' } }];
  }
  const projectId = q.project_id ? String(q.project_id).trim() : null;
  let limit = parseInt(q.limit, 10);
  if (!Number.isFinite(limit) || limit <= 0) limit = 20;
  if (limit > 100) limit = 100;

  return [{ json: {
    user_id: payload.sub,
    tenant_id: payload.tenant_id,
    role: payload.role || 'architect',
    request_id: 'req_' + Math.random().toString(36).slice(2, 10),
    agent_name: agentName,
    project_id: projectId,
    limit
  }}];
} catch (e) {
  return [{ json: { _error: 'AUTH_INVALID_TOKEN', _status: 401, _details: e.message } }];
}

const sess = $('Decode JWT + Query').first().json;
const rows = $input.all().map(i => i.json);
// La query ordena DESC para respetar el LIMIT (mas recientes), pero el frontend
// quiere mostrar cronologico ascendente.
const messages = rows.reverse().map(r => ({
  id: r.id,
  role: r.role,
  text: r.content,
  agent_name: r.agent_name,
  project_id: r.project_id,
  timestamp: r.created_at
}));
return [{ json: {
  data: {
    agent_name: sess.agent_name,
    project_id: sess.project_id,
    count: messages.length,
    messages
  },
  meta: {
    request_id: sess.request_id,
    timestamp: new Date().toISOString()
  }
}}];
